def find_solution(a: int, b: int, n: int):
    from math import gcd

    # If a or b are zero, handle separately
    if a == 0 and b == 0:
        return (0, 0) if n == 0 else "No solution"
    if a == 0:
        if b != 0 and n % b == 0 and n // b >= 0:
            return (0, n // b)
        else:
            return "No solution"
    if b == 0:
        if a != 0 and n % a == 0 and n // a >= 0:
            return (n // a, 0)
        else:
            return "No solution"

    d = gcd(a, b)
    if n % d != 0:
        return "No solution"

    # Extended Euclidean Algorithm to find one solution to a*x + b*y = d
    def extended_gcd(x, y):
        if y == 0:
            return (x, 1, 0)
        g, x1, y1 = extended_gcd(y, x % y)
        return (g, y1, x1 - (x // y) * y1)

    g, x0, y0 = extended_gcd(a, b)
    x0 *= n // g
    y0 *= n // g

    a_div = a // g
    b_div = b // g

    from math import ceil, floor

    # Solve inequalities for k:
    # x = x0 + k*b_div >= 0 => k >= -x0 / b_div if b_div != 0
    # y = y0 - k*a_div >= 0 => k <= y0 / a_div if a_div != 0

    # Handle zero denominators carefully
    if b_div == 0:
        # then x = x0 constant, check x0 >= 0
        if x0 < 0:
            return "No solution"
        else:
            # y = y0 - k * a_div >= 0 => k <= y0 / a_div
            # Need to find any integer k <= y0 / a_div
            # Since b_div=0, k can be any integer, so pick max k to get y >=0
            max_k = floor(y0 / a_div) if a_div != 0 else float('inf')
            # Choose k = max_k to find non-negative y
            k = max_k
    elif a_div == 0:
        # then y = y0 constant, check y0 >= 0
        if y0 < 0:
            return "No solution"
        else:
            # x = x0 + k * b_div >= 0 => k >= -x0 / b_div
            min_k = ceil(-x0 / b_div)
            k = min_k
    else:
        k_min = ceil(-x0 / b_div)
        k_max = floor(y0 / a_div)
        if k_min > k_max:
            return "No solution"
        k = k_min

    x = x0 + k * b_div
    y = y0 - k * a_div

    if x < 0 or y < 0:
        return "No solution"

    return (x, y)
