from typing import Optional, Tuple

def find_solution(a: int, b: int, n: int) -> Optional[Tuple[int, int]]:
    """
    Finds the first valid non-negative integer solution (x, y) to the equation:
        a*x + b*y = n

    Returns:
        A tuple (x, y) of the first non-negative integer solution found,
        or None if no solution exists.
    """
    if a == 0 and b == 0:
        # equation is 0 = n, solution only if n == 0
        if n == 0:
            return (0, 0)
        else:
            return None

    # If a == 0, equation reduces to b*y = n
    if a == 0:
        if b != 0 and n % b == 0 and n // b >= 0:
            return (0, n // b)
        else:
            return None

    # If b == 0, equation reduces to a*x = n
    if b == 0:
        if a != 0 and n % a == 0 and n // a >= 0:
            return (n // a, 0)
        else:
            return None

    # Determine max_x to limit search
    if a > 0:
        max_x = n // a if n >= 0 else 0
    else:
        # For a < 0, x >= 0 means a*x <= 0
        # Since searching infinite range is not feasible,
        # limit max_x to a reasonable upper bound:
        max_x = max(0, n + abs(a) * abs(n))

    for x in range(max_x + 1):
        rhs = n - a * x
        if rhs % b == 0:
            y = rhs // b
            if y >= 0:
                return (x, y)

    return None
```

