def compute_Last_Digit(a: int, b: int) -> int:
    if a > b:
        # Compute last digit of a! / b! = product of (b+1) to a
        product = 1
        for x in range(b + 1, a + 1):
            product = (product * (x % 10)) % 10
        return product
    else:
        # a <= b, treat as if a < b
        if a == b:
            return 1
        diff = b - a
        if diff >= 5:
            return 0
        product = 1
        for x in range(a + 1, b + 1):
            product = (product * (x % 10)) % 10
        return product
