from typing import Optional, Tuple
import math

def find_solution(a: int, b: int, n: int) -> Optional[Tuple[int, int]]:
    """
    Find non-negative integers x, y such that a*x + b*y = n.
    If no such non-negative integer solution exists, return None.

    Args:
        a (int): coefficient of x
        b (int): coefficient of y
        n (int): target integer

    Returns:
        Optional[Tuple[int, int]]: (x, y) if solution exists with x,y >= 0 else None
    """
    # Handle trivial cases
    if n < 0:
        return None
    if a == 0 and b == 0:
        return (0, 0) if n == 0 else None
    if a == 0:
        if b != 0 and n % b == 0 and n // b >= 0:
            return (0, n // b)
        return None
    if b == 0:
        if a != 0 and n % a == 0 and n // a >= 0:
            return (n // a, 0)
        return None

    # Extended Euclidean Algorithm to find one particular solution (x0, y0)
    def extended_gcd(aa: int, bb: int) -> Tuple[int, int, int]:
        if bb == 0:
            return aa, 1, 0
        gcd_, x1, y1 = extended_gcd(bb, aa % bb)
        x = y1
        y = x1 - (aa // bb) * y1
        return gcd_, x, y

    gcd_, x0, y0 = extended_gcd(a, b)
    if n % gcd_ != 0:
        return None

    # Scale the particular solution to n
    x0 *= n // gcd_
    y0 *= n // gcd_

    a_div = a // gcd_
    b_div = b // gcd_

    # x = x0 + k * b_div
    # y = y0 - k * a_div
    # Want x >= 0 and y >= 0

    # Find range for k from inequalities:
    # x0 + k*b_div >= 0  =>  k >= -x0 / b_div if b_div > 0 else k <= -x0 / b_div
    # y0 - k*a_div >= 0  =>  k <= y0 / a_div if a_div > 0 else k >= y0 / a_div

    if b_div > 0:
        k_min = math.ceil(-x0 / b_div)
    else:
        k_min = -math.inf if b_div < 0 else 0  # if b_div == 0, no k variation, handled above

    if a_div > 0:
        k_max = math.floor(y0 / a_div)
    else:
        k_max = math.inf if a_div < 0 else 0

    if k_min <= k_max:
        # Choose k such that x and y are both non-negative
        # Among all feasible k, try k_min to get smallest x
        k = k_min
        x = x0 + k * b_div
        y = y0 - k * a_div
        if x >= 0 and y >= 0:
            return (x, y)

        # If that didn't work due to rounding, try k_max
        k = k_max
        x = x0 + k * b_div
        y = y0 - k * a_div
        if x >= 0 and y >= 0:
            return (x, y)

        # Try all k in range [k_min, k_max]
        for k in range(k_min + 1, k_max):
            x = x0 + k * b_div
            y = y0 - k * a_div
            if x >= 0 and y >= 0:
                return (x, y)

    return None
```

