from collections.abc import Mapping

def dict_depth(d):
    """
    Compute the depth of a dictionary, counting nested dictionaries, lists, and tuples 
    as contributing to the same depth measure.

    Args:
        d (dict): The dictionary to measure.

    Returns:
        int: The depth of the dictionary.
    """
    if not isinstance(d, Mapping):
        return 0

    max_depth = 1
    for v in d.values():
        if isinstance(v, Mapping):
            depth = 1 + dict_depth(v)
            if depth > max_depth:
                max_depth = depth
        elif isinstance(v, (list, tuple)):
            inner_max = 0
            for item in v:
                depth = dict_depth(item)
                if depth > inner_max:
                    inner_max = depth
            if inner_max:
                depth = 1 + inner_max
                if depth > max_depth:
                    max_depth = depth
    return max_depth
```

