def next_smallest_palindrome(num: int) -> int:
    """
    Find the smallest palindrome strictly greater than the given number.
    """

    def mirror_left_to_right(s: str) -> str:
        n = len(s)
        half = n // 2
        if n % 2 == 0:
            # even length
            left = s[:half]
            return left + left[::-1]
        else:
            # odd length
            left = s[:half+1]
            return left + left[:-1][::-1]

    s = str(num + 1)  # strictly greater than num

    while True:
        # create palindrome by mirroring left to right
        p = mirror_left_to_right(s)
        if int(p) >= num + 1:
            return int(p)
        # increment the middle part and try again
        length = len(s)
        half = (length - 1) // 2
        if length % 2 == 0:
            left_part = s[:length//2]
            incremented = str(int(left_part) + 1)
            if len(incremented) > len(left_part):
                s = '1' + ('0' * (length - 1)) + '1'
            else:
                s = incremented + s[length//2:]
        else:
            left_part = s[:half+1]
            incremented = str(int(left_part) + 1)
            if len(incremented) > len(left_part):
                s = '1' + ('0' * (length - 1)) + '1'
            else:
                s = incremented + s[half+1:]
