def find_solution(a: int, b: int, n: int):
    """
    Find the first valid integer solution (x, y) to the equation a*x + b*y = n,
    where x and y are non-negative integers, by scanning x from 0 upward.

    Returns:
        A tuple (x, y) if a solution exists, otherwise None.
    """
    if a == 0 and b == 0:
        return (0, 0) if n == 0 else None

    if a == 0:
        if b != 0 and n % b == 0 and n // b >= 0:
            return (0, n // b)
        else:
            return None

    if b == 0:
        if a != 0 and n % a == 0 and n // a >= 0:
            return (n // a, 0)
        else:
            return None

    x = 0
    while True:
        remainder = n - a * x
        if remainder < 0:
            return None
        if b != 0 and remainder % b == 0:
            y = remainder // b
            if y >= 0:
                return (x, y)
        x += 1
