def smallest_missing(arr: List[int]) -> int:
    """
    Find the smallest missing non-negative integer from the input array.
    The smallest missing integer is the smallest integer >= 0 that does not appear in arr.
    """
    n = len(arr)
    present = [False] * (n + 1)
    for num in arr:
        if 0 <= num <= n:
            present[num] = True
    for i in range(n + 1):
        if not present[i]:
            return i
