def next_smallest_palindrome(num: int) -> int:
    """
    Returns the next smallest palindrome strictly greater than the given number.
    """
    def next_palindrome(n: int) -> int:
        s = str(n)
        length = len(s)

        if set(s) == {'9'}:
            # If all digits are 9, next palindrome is 10...01 (length+1 digits)
            return n + 2  # For example 9 -> 11, 99 -> 101, 999 -> 1001

        half_len = (length + 1) // 2
        left = s[:half_len]

        if length % 2 == 0:
            palindrome = left + left[::-1]
        else:
            palindrome = left + left[:-1][::-1]

        palindrome_num = int(palindrome)
        if palindrome_num >= n:
            return palindrome_num

        # Increment the left half and form the palindrome again
        left_num = int(left)
        left_num += 1
        left = str(left_num)
        if len(left) > half_len:
            # This happens when we have carry-over, e.g. 999 + 1 = 1000
            if length % 2 == 0:
                palindrome = left + left[:-1][::-1]
            else:
                palindrome = left + left[:-1][::-1]
        else:
            if length % 2 == 0:
                palindrome = left + left[::-1]
            else:
                palindrome = left + left[:-1][::-1]

        return int(palindrome)

    # Start searching from num+1 since we want strictly greater palindrome
    candidate = num + 1
    return next_palindrome(candidate)
