from typing import Optional, Tuple

def find_solution(a: int, b: int, n: int) -> Optional[Tuple[int, int]]:
    """
    Find one integer solution (x, y) to the equation a*x + b*y = n.
    Returns None if no solution exists.
    """
    def extended_gcd(aa: int, bb: int) -> Tuple[int, int, int]:
        # Returns a tuple (g, x, y) such that aa*x + bb*y = g = gcd(aa, bb)
        if bb == 0:
            return (aa, 1, 0)
        g, x1, y1 = extended_gcd(bb, aa % bb)
        x = y1
        y = x1 - (aa // bb) * y1
        return (g, x, y)

    g, x0, y0 = extended_gcd(a, b)
    if n % g != 0:
        return None
    scale = n // g
    return (x0 * scale, y0 * scale)
