def find_solution(a: int, b: int, n: int):
    """
    Find the first non-negative integer solution (x, y) to the equation a*x + b*y = n,
    scanning x upward from 0.

    Returns:
        A tuple (x, y) of integers if a solution exists,
        or None if no non-negative integer solution exists.
    """
    if a == 0 and b == 0:
        # Equation reduces to 0 = n; only solution if n == 0
        return (0, 0) if n == 0 else None

    if a == 0:
        # Equation reduces to b*y = n
        if b == 0:
            return None
        if n % b == 0 and n // b >= 0:
            return (0, n // b)
        else:
            return None

    if b == 0:
        # Equation reduces to a*x = n
        if n % a == 0 and n // a >= 0:
            return (n // a, 0)
        else:
            return None

    x = 0
    # Modify loop condition to handle negative a and b properly
    # We want to scan x upwards from 0 and stop when a*x > n if a>0 or when a*x < n if a<0
    if a > 0:
        while a * x <= n:
            remainder = n - a * x
            if remainder % b == 0:
                y = remainder // b
                if y >= 0:
                    return (x, y)
            x += 1
    else:
        # a < 0
        # Since x >= 0 and a < 0, a*x <= 0
        # We can scan x upward until a*x < n is no longer true
        while a * x >= n:
            remainder = n - a * x
            if remainder % b == 0:
                y = remainder // b
                if y >= 0:
                    return (x, y)
            x += 1
    return None
