from collections.abc import Iterable

def substract_elements(data):
    """
    Recursively subtract elements in nested collections.
    For each iterable (list, tuple, set), the subtraction is performed cumulatively:
    result = first_element - second_element - third_element - ...
    Non-iterable elements (ints, floats) are returned as is.

    The output matches the input structure but with values replaced by their cumulative subtraction.

    Examples:
    substract_elements([10, 3, 2]) -> 5 (10 - 3 - 2)
    substract_elements([10, [3, 2]]) -> [10, 1] (10, (3 - 2))
    substract_elements((20, (5, 3, 1))) -> (20, 1) (20, (5 - 3 -1))
    substract_elements({10, 3}) -> 7 (10 - 3 or 3 - 10, order undefined for set, so convert to list first)
    """
    def subtract_iterable(iterable):
        # Convert sets to sorted list to have deterministic order
        if isinstance(iterable, set):
            items = sorted(iterable)
        else:
            items = list(iterable)
        if not items:
            raise ValueError("Empty iterable cannot be subtracted")
        first = process_element(items[0])
        for elem in items[1:]:
            first -= process_element(elem)
        return first

    def process_element(elem):
        if isinstance(elem, (str, bytes)):
            # Strings and bytes are not considered as nested collections here
            return elem
        if isinstance(elem, Iterable):
            # For iterable collections (except str/bytes), recurse
            if isinstance(elem, list):
                # If all elements are non-iterable or str/bytes, do cumulative subtraction
                if all(not isinstance(x, Iterable) or isinstance(x, (str, bytes)) for x in elem):
                    return subtract_iterable(elem)
                else:
                    return [process_element(x) for x in elem]
            elif isinstance(elem, tuple):
                # If all elements are non-iterable or str/bytes, do cumulative subtraction
                if all(not isinstance(x, Iterable) or isinstance(x, (str, bytes)) for x in elem):
                    return subtract_iterable(elem)
                else:
                    return tuple(process_element(x) for x in elem)
            elif isinstance(elem, set):
                # Return subtraction result as a number since set has no order or structure
                return subtract_iterable(elem)
            else:
                # For other iterable types, treat as list
                return [process_element(x) for x in elem]
        else:
            # Non-iterable element, return as-is (assumed numeric)
            return elem

    # If top level is iterable and not str/bytes, compute subtraction cumulatively or recursively
    if isinstance(data, (str, bytes)):
        return data
    if isinstance(data, Iterable):
        # If top-level is set, return a single value after subtraction
        if isinstance(data, set):
            return subtract_iterable(data)
        # If top-level is tuple or list, return same structure but with elements processed recursively
        if isinstance(data, list):
            if all(not isinstance(x, Iterable) or isinstance(x, (str, bytes)) for x in data):
                return subtract_iterable(data)
            else:
                return [process_element(x) for x in data]
        if isinstance(data, tuple):
            if all(not isinstance(x, Iterable) or isinstance(x, (str, bytes)) for x in data):
                return subtract_iterable(data)
            else:
                return tuple(process_element(x) for x in data)
        # For other iterable types, treat as list
        return [process_element(x) for x in data]
    else:
        # Single element, return as is
        return data
