def next_smallest_palindrome(num: int) -> int:
    s = str(num)
    length = len(s)

    if all(ch == '9' for ch in s):
        return int('1' + ('0' * (length - 1)) + '1')

    def make_palindrome(left: str, odd_length: bool) -> str:
        if odd_length:
            return left + left[-2::-1]
        else:
            return left + left[::-1]

    def increment_str_num(x: str) -> str:
        incremented = str(int(x) + 1)
        return incremented

    odd = (length % 2 != 0)
    mid = length // 2

    if odd:
        left = s[:mid+1]
    else:
        left = s[:mid]

    palindrome = make_palindrome(left, odd)

    if int(palindrome) > num:
        return int(palindrome)

    left_inc = increment_str_num(left)

    if len(left_inc) > len(left):
        if odd:
            palindrome = make_palindrome(left_inc, True)
        else:
            palindrome = make_palindrome(left_inc, False)
        return int(palindrome)

    palindrome = make_palindrome(left_inc, odd)
    return int(palindrome)
