def find_solution(a: int, b: int, n: int):
    """
    Find the smallest non-negative integer x such that (n - a*x) is divisible by b,
    and return the corresponding integer y = (n - a*x) // b.
    Returns a tuple (x, y) if a solution exists, otherwise None.
    """
    if b == 0:
        # If b is zero, equation reduces to a*x = n
        if a == 0:
            return (0, 0) if n == 0 else None
        if n % a == 0 and n // a >= 0:
            return (n // a, 0)
        return None

    x = 0
    while True:
        remainder = n - a * x
        if a >= 0 and remainder < 0:
            # Since x is increasing and a*x grows, no further x will satisfy
            return None
        if a < 0 and remainder > n:
            # If a < 0, a*x decreases as x increases; stop if remainder > n (no progress)
            return None
        if remainder % b == 0:
            y = remainder // b
            return (x, y)
        x += 1
