def monotonic(l):
    """
    Return True if list elements are monotonically increasing or decreasing and no duplicates,
    else False. Also return sum of list elements if True.

    For strings, return True if characters are alphabetically or reverse alphabetically ordered
    and no duplicates, else False. Also return original string if True.

    Does not use loops or in-built sorting methods.

    >>> monotonic([1, 2, 4, 20])
    (True, 27)
    >>> monotonic([1, 1, 20, 4, 10])
    False
    >>> monotonic([4, 1, 0, -10])
    (True, -5)
    >>> monotonic("abcd")
    (True, 'abcd')
    >>> monotonic("abca")
    False
    >>> monotonic("dcba")
    (True, 'dcba')
    """
    def no_duplicates(seq):
        return len(set(seq)) == len(seq)

    def is_monotonic_asc(seq):
        if len(seq) < 2:
            return True
        return seq[0] < seq[1] and is_monotonic_asc(seq[1:])

    def is_monotonic_desc(seq):
        if len(seq) < 2:
            return True
        return seq[0] > seq[1] and is_monotonic_desc(seq[1:])

    if isinstance(l, list):
        if not no_duplicates(l):
            return False
        if is_monotonic_asc(l) or is_monotonic_desc(l):
            return True, sum(l)
        else:
