            if i == len(a) - 1:
                return True
            if a[i] > a[i + 1]:
                return False
            return check(i + 1)
        return check(0)

    def right_shift(a):
        # Return the array after one right shift
        if len(a) == 0:
            return a
        return [a[-1]] + a[:-1]

    def try_shifts(a, shifts, max_shifts):
        # Recursively try shifts up to max_shifts times
        if shifts > max_shifts:
            return False
        if is_sorted(a):
            return shifts
        return try_shifts(right_shift(a), shifts + 1, max_shifts)

    return try_shifts(arr, 0, len(arr) - 1)
