from typing import List, Union

def select_words(s: Union[str, int], n: int) -> List[str]:
    """
    Given a string s and a natural number n, returns a list of words from s that contain exactly n consonants,
    preserving their original order.
    If s is empty, returns an empty string.
    The output list is sorted alphabetically but maintains the original order of words.
    The function uses no loops and has O(1) complexity in terms of iteration (uses recursion).
    The input can be string or int, but works only for strings meaningfully.
    """
    if not isinstance(s, str) or s == "":
        return ""

    vowels = set("aeiouAEIOU")

    def consonant_count(word: str) -> int:
        # Count consonants recursively (no loops)
        if word == "":
            return 0
        head, tail = word[0], word[1:]
        if head.isalpha() and head not in vowels:
            return 1 + consonant_count(tail)
        return consonant_count(tail)

    words = s.split()

    # Helper to select words that have exactly n consonants, recursively
    def select_rec(words_list: List[str], acc: List[str]) -> List[str]:
        if not words_list:
            # Sort acc alphabetically but maintain original order among duplicates
            # Since we must preserve original order, stable sort is enough
            # sorted() in Python is stable
            return sorted(acc, key=lambda x: x.lower())
        first, *rest = words_list
        if consonant_count(first) == n:
            return select_rec(rest, acc + [first])
        else:
            return select_rec(rest, acc)

    return select_rec(words, [])
