def parse_nested_parens(paren_string):
    """ Input to this function is a string. Output the deepest level of nesting of parentheses.
    """
    max_depth = 0
    current_depth = 0
    for char in paren_string:
        if char == '(':
            current_depth += 1
            if current_depth > max_depth:
                max_depth = current_depth
        elif char == ')':
            current_depth -= 1
            if current_depth < 0:
                # Unbalanced parentheses (more closing than opening)
                current_depth = 0
    return max_depth
